const timestamp = Date.now().toString(16).padStart(8, '0').slice(-8);
const random1 = Math.floor(Math.random() * 0xFFFFFFFF).toString(16).padStart(8, '0');
const random2 = Math.floor(Math.random() * 0xFFFFFFFF).toString(16).padStart(8, '0');
const id_request = [timestamp, random1, random2].join('-');

const dic = {
  id_request,
  ID_SESSION: $('Telegram Trigger').item.json.message.chat.id,
  NAME: $('Telegram Trigger').item.json.message.from.first_name,
  QUESTION: $('Telegram Trigger').item.json.message.text,
  MESSAGE_COUNT: $input.first().json.MESSAGE_COUNT,
  SUMMARY: $input.first().json.SUMMARY,
  KEY_DATA: $input.first().json.KEY_DATA,
  LAST_UPDATED: $input.first().json.LAST_UPDATED,
  useContext:'true'
};

return [{ json: dic }];

